
local pctxu=[==[]==]
local smkbo=
(function(...)
local nyp={14,92,219,39,119,102,197,226,181,29,27,25,186,186,99,209}
local epf=bit32 or bit
local vvow=epf.bxor
for rscaa=1,#nyp do nyp[rscaa]=vvow(nyp[rscaa],(153*rscaa+241)%256) end
local ux="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lwp={}
for mbqhk=1,#ux do lwp[ux:byte(mbqhk)]=mbqhk-1 end
local function no(str)
  local R={} local acc,nb=0,0
  for vnjff=1,#str do
    local v=lwp[str:byte(vnjff)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function jkyq(key,data)
  local S={} for kz=0,255 do S[kz]=kz end
  local j=0
  for agrd=0,255 do
    j=(j+S[agrd]+key[(agrd%#key)+1])%256
    S[agrd],S[j]=S[j],S[agrd]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(vvow(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=jkyq(nyp,no(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local bs=nf()
return function(big) return bs(big) end
end)(...)

return smkbo(pctxu)
